```go
package ratelimit

import (
	"context"
	"fmt"
	"time"

	"github.com/redis/go-redis/v9"
)

// Tier defines a rate limit tier with its constraints
type Tier struct {
	Name      string
	Capacity  float64       // Maximum tokens in the bucket
	RefillRate float64      // Tokens added per second
	Window    time.Duration // Time window for the tier
}

// RateLimiter implements a distributed token bucket rate limiter using Redis
type RateLimiter struct {
	client *redis.Client
	tiers  map[string]*Tier
}

// NewRateLimiter creates a new distributed rate limiter
func NewRateLimiter(client *redis.Client, tiers map[string]*Tier) *RateLimiter {
	return &RateLimiter{
		client: client,
		tiers:  tiers,
	}
}

// Allow checks if a request is allowed under the given tier
// Returns (allowed bool, remaining tokens, reset time)
func (rl *RateLimiter) Allow(ctx context.Context, identifier string, tierName string) (bool, float64, time.Time, error) {
	tier, exists := rl.tiers[tierName]
	if !exists {
		return false, 0, time.Time{}, fmt.Errorf("tier %q not found", tierName)
	}

	key := fmt.Sprintf("ratelimit:%s:%s", tierName, identifier)
	now := time.Now()

	// Use Lua script for atomic operations
	result, err := rl.client.Eval(ctx, tokenBucketScript, []string{key}, 
		tier.Capacity, tier.RefillRate, now.UnixNano()).Result()
	if err != nil {
		return false, 0, time.Time{}, err
	}

	// Parse Lua script response: [allowed, remaining_tokens, reset_time_ns]
	values := result.([]interface{})
	allowed := values[0].(int64) == 1
	remaining := values[1].(float64)
	resetTimeNs := values[2].(int64)
	resetTime := time.Unix(0, resetTimeNs)

	return allowed, remaining, resetTime, nil
}

// AllowN checks if N tokens can be consumed
func (rl *RateLimiter) AllowN(ctx context.Context, identifier string, tierName string, tokens float64) (bool, float64, time.Time, error) {
	tier, exists := rl.tiers[tierName]
	if !exists {
		return false, 0, time.Time{}, fmt.Errorf("tier %q not found", tierName)
	}

	key := fmt.Sprintf("ratelimit:%s:%s", tierName, identifier)
	now := time.Now()

	result, err := rl.client.Eval(ctx, tokenBucketScriptN, []string{key},
		tier.Capacity, tier.RefillRate, now.UnixNano(), tokens).Result()
	if err != nil {
		return false, 0, time.Time{}, err
	}

	values := result.([]interface{})
	allowed := values[0].(int64) == 1
	remaining := values[1].(float64)
	resetTimeNs := values[2].(int64)
	resetTime := time.Unix(0, resetTimeNs)

	return allowed, remaining, resetTime, nil
}

// GetStatus returns the current status of a rate limit bucket
func (rl *RateLimiter) GetStatus(ctx context.Context, identifier string, tierName string) (float64, time.Time, error) {
	tier, exists := rl.tiers[tierName]
	if !exists {
		return 0, time.Time{}, fmt.Errorf("tier %q not found", tierName)
	}

	key := fmt.Sprintf("ratelimit:%s:%s", tierName, identifier)
	now := time.Now()

	result, err := rl.client.Eval(ctx, getStatusScript, []string{key},
		tier.Capacity, tier.RefillRate, now.UnixNano()).Result()
	if err != nil {
		return 0, time.Time{}, err
	}

	values := result.([]interface{})
	tokens := values[0].(float64)
	resetTimeNs := values[1].(int64)
	resetTime := time.Unix(0, resetTimeNs)

	return tokens, resetTime, nil
}

// Reset clears the rate limit for an identifier
func (rl *RateLimiter) Reset(ctx context.Context, identifier string, tierName string) error {
	key := fmt.Sprintf("ratelimit:%s:%s", tierName, identifier)
	return rl.client.Del(ctx, key).Err()
}

// Lua script for token bucket algorithm (consume 1 token)
// Returns: [allowed (0/1), remaining_tokens, reset_time_ns]
const tokenBucketScript = `
local key = KEYS[1]
local capacity = tonumber(ARGV[1])
local refill_rate = tonumber(ARGV[2])
local now_ns = tonumber(ARGV[3])

local bucket = redis.call('HMGET', key, 'tokens', 'last_refill_ns')
local tokens = tonumber(bucket[1]) or capacity
local last_refill_ns = tonumber(bucket[2]) or now_ns

-- Calculate elapsed time and refill tokens
local elapsed_ns = math.max(0, now_ns - last_refill_ns)
local elapsed_s = elapsed_ns / 1e9
local refilled = elapsed_s * refill_rate
tokens = math.min(capacity, tokens + refilled)

-- Try to consume 1 token
local allowed = 0
if tokens >= 1 then
	allowed = 1
	tokens = tokens - 1
end

-- Update bucket state
redis.call('HSET', key, 'tokens', tokens, 'last_refill_ns', now_ns)
redis.call('EXPIRE', key, math.ceil(capacity / refill_rate) + 1)

-- Calculate reset time (when bucket will be full)
local tokens_needed = capacity - tokens
local reset_time_ns = now_ns + (tokens_needed / refill_rate * 1e9)

return {allowed, tokens, reset_time_ns}
`

// Lua script for consuming N tokens
// Returns: [allowed (0/1), remaining_tokens, reset_time_ns]
const tokenBucketScriptN = `
local key = KEYS[1]
local capacity = tonumber(ARGV[1])
local refill_rate = tonumber(ARGV[2])
local now_ns = tonumber(ARGV[3])
local tokens_requested = tonumber(ARGV[4])

local bucket = redis.call('HMGET', key, 'tokens', 'last_refill_ns')
local tokens = tonumber(bucket[1]) or capacity
local last_refill_ns = tonumber(bucket[2]) or now_ns

-- Calculate elapsed time and refill tokens
local elapsed_ns = math.max(0, now_ns - last_refill_ns)
local elapsed_s = elapsed_ns / 1e9
local refilled = elapsed_s * refill_rate
tokens = math.min(capacity, tokens + refilled)

-- Try to consume requested tokens
local allowed = 0
if tokens >= tokens_requested then
	allowed = 1
	tokens = tokens - tokens_requested
end

-- Update bucket state
redis.call('HSET', key, 'tokens', tokens, 'last_refill_ns', now_ns)
redis.call('EXPIRE', key, math.ceil(capacity / refill_rate) + 1)

-- Calculate reset time
local tokens_needed = capacity - tokens
local reset_time_ns = now_ns + (tokens_needed / refill_rate * 1e9)

return {allowed, tokens, reset_time_ns}
`

// Lua script to get current status without consuming tokens
// Returns: [tokens, reset_time_ns]
const getStatusScript = `
