local capacity = tonumber(ARGV[1])
local refill_rate = tonumber(ARGV[2])
local now_ns = tonumber(ARGV[3])

local bucket = redis.call('HMGET', key, 'tokens', 'last_refill_ns')
local tokens = tonumber(bucket[1]) or capacity
local last_refill_ns = tonumber(bucket[2]) or now_ns

-- Calculate elapsed time and refill tokens
local elapsed_ns = math.max(0, now_ns - last_refill_ns)
local elapsed_s = elapsed_ns / 1e9
local refilled = elapsed_s * refill_rate
