package main

import (
	"context"
	"fmt"
	"log"
	"net/http"
	"time"

	"github.com/redis/go-redis/v9"
)

func main() {
	// Initialize Redis client
	client := redis.NewClient(&redis.Options{
		Addr: "localhost:6379",
	})
	defer client.Close()

	// Define rate limit tiers
	tiers := map[string]*ratelimit.Tier{
		"free": {
			Name:       "free",
			Capacity:   10,
			RefillRate: 1,    // 1 token per second
			Window:     time.Second,
		},
		"pro": {
			Name:       "pro",
			Capacity:   100,
			RefillRate: 10,   // 10 tokens per second
			Window:     time.Second,
		},
		"enterprise": {
			Name:       "enterprise",
			Capacity:   1000,
			RefillRate: 100,  // 100 tokens per second
			Window:     time.Second,
		},
	}

	limiter := ratelimit.NewRateLimiter(client, tiers)

	// Example 1: Simple rate limit check
	ctx := context.Background()
	userID := "user:123"

	allowed, remaining, resetTime, err := limiter.Allow(ctx, userID, "pro")
	if err != nil {
		log.Fatal(err)
	}

	fmt.Printf("Allowed: %v, Remaining: %.2f, Reset: %v\n", allowed, remaining, resetTime)

	// Example 2: Consume multiple tokens
	allowed, remaining, resetTime, err = limiter.AllowN(ctx, userID, "pro", 5)
	if err != nil {
		log.Fatal(err)
	}

	fmt.Printf("Allowed (5 tokens): %v, Remaining: %.2f\n", allowed, remaining)

	// Example 3: HTTP middleware
	http.HandleFunc("/api/data", rateLimitMiddleware(limiter, "pro")(handleData))
	http.ListenAndServe(":8080", nil)
}

// rateLimitMiddleware returns a middleware that enforces rate limiting
func rateLimitMiddleware(limiter *ratelimit.RateLimiter, tier string) func(http.Handler) http.Handler {
	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			// Extract user identifier (could be from auth, IP, etc.)
			userID := r.Header.Get("X-User-ID")
			if userID == "" {
				userID = r.RemoteAddr
			}

			allowed, remaining, resetTime, err := limiter.Allow(r.Context(), userID, tier)
			if err != nil {
				http.Error(w, "Rate limiter error", http.StatusInternalServerError)
				return
			}

			// Set rate limit headers
			w.Header().Set("X-RateLimit-Remaining", fmt.Sprintf("%.0f", remaining))
			w.Header().Set("X-RateLimit-Reset", fmt.Sprintf("%d", resetTime.Unix()))

			if !allowed {
				w.Header().Set("Retry-After", fmt.Sprintf("%d", int(time.Until(resetTime).Seconds())+1))
				http.Error(w, "Rate limit exceeded", http.StatusTooManyRequests)
				return
			}

			next.ServeHTTP(w, r)
		})
	}
}

func handleData(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	fmt.Fprintf(w, `{"status":"ok","data":"your data here"}`)
}
```

Key features of this implementation:

- **Token bucket algorithm**: Tokens refill at a constant rate; requests consume tokens. Requests are allowed if tokens are available.
- **Atomic operations**: Uses Lua scripts to ensure thread-safe operations across distributed systems.
- **Multiple tiers**: Support for different rate limit configurations (free, pro, enterprise).
- **Precise timing**: Uses nanosecond precision for accurate token calculation.
- **Reset tracking**: Returns when the bucket will be full, useful for client backoff strategies.
- **Status queries**: Check current tokens without consuming them.
- **HTTP middleware**: Ready-to-use middleware with standard rate limit headers.

The Lua scripts handle the core logic atomically in Redis, preventing race conditions in distributed environments. Each identifier gets its own bucket tracked by tier, allowing fine-grained control per user and tier combination.

I'll create a comprehensive, thread-safe event bus implementation with all the features you requested.

```java
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.locks.ReadWriteLock;
import java.util.concurrent.locks.ReentrantReadWriteLock;
import java.util.function.Consumer;
import java.util.stream.Collectors;

/**
 * A thread-safe event bus supporting subscriber filtering, priority-based delivery,
 * and both synchronous and asynchronous event execution.
 */
public class EventBus {
    private static final int DEFAULT_THREAD_POOL_SIZE = Runtime.getRuntime().availableProcessors();
    private static final int DEFAULT_QUEUE_CAPACITY = 1000;

    private final Map<Class<?>, List<Subscription<?>>> subscriptions = new ConcurrentHashMap<>();
    private final ReadWriteLock lock = new ReentrantReadWriteLock();
    private final ExecutorService executorService;
    private final boolean ownsExecutor;
    private volatile boolean closed = false;

    /**
     * Creates an EventBus with a default thread pool.
     */
    public EventBus() {
        this(Executors.newFixedThreadPool(DEFAULT_THREAD_POOL_SIZE,
                new ThreadFactory() {
                    private final AtomicInteger count = new AtomicInteger(0);
                    @Override
                    public Thread newThread(Runnable r) {
                        Thread t = new Thread(r, "EventBus-" + count.incrementAndGet());
                        t.setDaemon(true);
                        return t;
                    }
                }), true);
    }

    /**
     * Creates an EventBus with a custom executor service.
     * The EventBus will not shut down the provided executor.
     */
    public EventBus(ExecutorService executorService) {
        this(executorService, false);
    }

    private EventBus(ExecutorService executorService, boolean ownsExecutor) {
        this.executorService = Objects.requireNonNull(executorService, "executorService cannot be null");
        this.ownsExecutor = ownsExecutor;
    }

    /**
     * Subscribes to events of a specific type with default settings (sync, normal priority).
     */
    public <T> Subscription<T> subscribe(Class<T> eventType, Consumer<T> handler) {
        return subscribe(eventType, handler, ExecutionMode.SYNC, Priority.NORMAL, null);
    }

    /**
     * Subscribes to events with a filter predicate.
     */
    public <T> Subscription<T> subscribe(Class<T> eventType, Consumer<T> handler, 
                                         ExecutionMode mode, Priority priority, 
                                         java.util.function.Predicate<T> filter) {
        checkNotClosed();
        Objects.requireNonNull(eventType, "eventType cannot be null");
        Objects.requireNonNull(handler, "handler cannot be null");
        Objects.requireNonNull(mode, "mode cannot be null");
        Objects.requireNonNull(priority, "priority cannot be null");

        Subscription<T> subscription = new Subscription<>(eventType, handler, mode, priority, filter);

        lock.writeLock().lock();
        try {
            subscriptions.computeIfAbsent(eventType, k -> new CopyOnWriteArrayList<>())
                    .add(subscription);
            // Sort by priority after adding
            sortSubscriptionsByPriority(eventType);
        } finally {
            lock.writeLock().unlock();
        }

        return subscription;
    }

    /**
     * Publishes an event to all matching subscribers.
     */
    public <T> void publish(T event) {
        checkNotClosed();
        Objects.requireNonNull(event, "event cannot be null");

        Class<?> eventType = event.getClass();
        List<Subscription<?>> subs = getSubscriptionsForType(eventType);

        for (Subscription<?> sub : subs) {
            if (sub.isActive()) {
                deliverEvent(sub, event);
            }
        }
    }

    /**
     * Publishes an event and waits for all synchronous handlers to complete.
     * Asynchronous handlers are submitted but not waited for.
     */
    public <T> void publishAndWait(T event) throws InterruptedException {
        checkNotClosed();
        Objects.requireNonNull(event, "event cannot be null");

        Class<?> eventType = event.getClass();
        List<Subscription<?>> subs = getSubscriptionsForType(eventType);
        List<Future<?>> asyncFutures = new ArrayList<>();

        for (Subscription<?> sub : subs) {
            if (sub.isActive()) {
                if (sub.mode == ExecutionMode.SYNC) {
                    deliverEvent(sub, event);
                } else {
                    asyncFutures.add(submitAsyncEvent(sub, event));
                }
            }
        }

        // Wait for all async handlers to complete
        for (Future<?> future : asyncFutures) {
            try {
                future.get();
            } catch (ExecutionException e) {
                // Log but don't rethrow to allow other handlers to complete
                Thread.currentThread().getUncaughtExceptionHandler()
                        .uncaughtException(Thread.currentThread(), e.getCause());
            }
        }
    }

    /**
     * Unsubscribes a specific subscription.
     */
    public <T> void unsubscribe(Subscription<T> subscription) {
        checkNotClosed();
        Objects.requireNonNull(subscription, "subscription cannot be null");

        lock.writeLock().lock();
        try {
            List<Subscription<?>> subs = subscriptions.get(subscription.eventType);
            if (subs != null) {
                subs.remove(subscription);
            }
        } finally {
            lock.writeLock().unlock();
        }
    }

    /**
     * Unsubscribes all subscribers for a specific event type.
     */
    public void unsubscribeAll(Class<?> eventType) {
        checkNotClosed();
        Objects.requireNonNull(eventType, "eventType cannot be null");

        lock.writeLock().lock();
        try {
            subscriptions.remove(eventType);
        } finally {
            lock.writeLock().unlock();
        }
    }

    /**
     * Returns the number of active subscribers for an event type.
     */
    public int getSubscriberCount(Class<?> eventType) {
        lock.readLock().lock();
        try {
            List<Subscription<?>> subs = subscriptions.get(eventType);
            return subs != null ? (int) subs.stream().filter(Subscription::isActive).count() : 0;
        } finally {
            lock.readLock().unlock();
        }
    }

    /**
     * Shuts down the event bus and its executor service (if owned).
     */
    public void shutdown() {
        closed = true;
        if (ownsExecutor) {
            executorService.shutdown();
            try {
                if (!executorService.awaitTermination(10, TimeUnit.SECONDS)) {
                    executorService.shutdownNow();
                }
            } catch (InterruptedException e) {
                executorService.shutdownNow();
                Thread.currentThread().interrupt();
            }
        }
    }

    // Private helper methods

    @SuppressWarnings("unchecked")
    private <T> void deliverEvent(Subscription<?> subscription, T event) {
        Subscription<T> typedSub = (Subscription<T>) subscription;

        if (typedSub.filter != null && !typedSub.filter.test(event)) {
            return;
        }

        try {
            if (typedSub.mode == ExecutionMode.SYNC) {
                typedSub.handler.accept(event);
            } else {
                submitAsyncEvent(typedSub, event);
            }
        } catch (Exception e) {
            handleException(e, typedSub, event);
        }
    }

    @SuppressWarnings("unchecked")
    private <T> Future<?> submitAsyncEvent(Subscription<?> subscription, T event) {
        Subscription<T> typedSub = (Subscription<T>) subscription;
        return executorService.submit(() -> {
            try {
                typedSub.handler.accept(event);
            } catch (Exception e) {
                handleException(e, typedSub, event);
            }
        });
    }

    private <T> void handleException(Exception e, Subscription<T> subscription, T event) {
        System.err.println("Error delivering event " + event.getClass().getSimpleName() + 
                          " to subscriber: " + e.getMessage());
        e.printStackTrace();
    }

    private List<Subscription<?>> getSubscriptionsForType(Class<?> eventType) {
        lock.readLock().lock();
        try {
            List<Subscription<?>> subs = subscriptions.get(eventType);
            return subs != null ? new ArrayList<>(subs) : Collections.emptyList();
        } finally {
            lock.readLock().unlock();
        }
    }

    private void sortSubscriptionsByPriority(Class<?> eventType) {
        List<Subscription<?>> subs = subscriptions.get(eventType);
        if (subs != null) {
            subs.sort((s1, s2) -> s2.priority.compareTo(s1.priority));
        }
    }

    private void checkNotClosed() {
        if (closed) {
            throw new IllegalStateException("EventBus is closed");
        }
    }

    /**
     * Represents a subscription to events.
     */
    public static class Subscription<T> {
        private final Class<T> eventType;
        private final Consumer<T> handler;
        private final ExecutionMode mode;
        private final Priority priority;
        private final java.util.function.Predicate<T> filter;
        private volatile boolean active = true;

        private Subscription(Class<T> eventType, Consumer<T> handler, ExecutionMode mode,
                           Priority priority, java.util.function.Predicate<T> filter) {
            this.eventType = eventType;
            this.handler = handler;
            this.mode = mode;
            this.priority = priority;
            this.filter = filter;
        }

        /**
         * Deactivates this subscription without removing it.
         */
        public void deactivate() {
            this.active = false;
        }

        /**
         * Reactivates this subscription.
         */
        public void reactivate() {
            this.active = true;
        }

        public boolean isActive() {
            return active;
        }

        public Priority getPriority() {
            return priority;
        }

        public ExecutionMode getMode() {
            return mode;
        }
    }

    /**
     * Execution mode for event handlers.
     */
    public enum ExecutionMode {
        SYNC,   // Execute in the calling thread
        ASYNC   // Execute in a thread pool
    }

    /**
     * Priority levels for event delivery.
     */
    public enum Priority {
        CRITICAL(3),
        HIGH(2),
        NORMAL(1),
        LOW(0);

        private final int level;

        Priority(int level) {
            this.level = level;
        }
    }
}
