        eventBus.subscribe(OrderPlacedEvent.class,
                event -> System.out.println("Processing regular order: " + event.orderId),
                EventBus.ExecutionMode.ASYNC,
                EventBus.Priority.NORMAL,
                event -> event.amount <= 1000);

