This is solid work. You've built a production-grade virtual scroller with the right tradeoffs. Let me review the implementation and suggest a few refinements.

**What works well:**
- Binary search for finding visible range is the right call for performance
- Height caching with position invalidation is clean
- Overscan buffer prevents flashing during scroll
- DOM structure (virtual container + absolute positioning) is standard and efficient

**Issues to address:**

1. **Position cache invalidation is incomplete.** When you update a height, you invalidate positions for items after it, but you don't re-render. If the user scrolls back up, they'll see stale positions.

2. **Binary search can fail with unmeasured items.** If items haven't been measured yet, `getItemPosition()` returns estimated heights, which breaks the search invariant. You need to handle this.

3. **Memory leak in scroll handler.** The arrow function captures `this`, but you're not storing the bound reference, so `removeEventListener` won't work in `destroy()`.

4. **Resize handling doesn't account for height changes.** If content reflows (font size change, window resize), item heights change but you don't remeasure.

Here's the corrected version:

```javascript
class VirtualScroller {
  constructor(options = {}) {
    this.container = options.container;
    this.items = options.items || [];
    this.itemRenderer = options.itemRenderer;
    this.estimatedItemHeight = options.estimatedItemHeight || 50;
    this.overscan = options.overscan || 3;
    this.onScroll = options.onScroll;
    this.scrollSmoothing = options.scrollSmoothing !== false;

    this.scrollTop = 0;
    this.containerHeight = 0;
    this.itemHeights = new Map();
    this.itemPositions = new Map();
    this.visibleRange = { start: 0, end: 0 };
    this.scrollTimeout = null;
    this.isScrolling = false;
    this.dirtyStart = Infinity; // Track which positions need recalculation

    this.virtualContainer = null;
    this.viewport = null;
    this.itemsContainer = null;

    // Bind handlers for proper cleanup
    this.handleScroll = this.handleScroll.bind(this);
    this.handleResize = this.handleResize.bind(this);

    this.init();
  }

  init() {
    this.setupDOM();
    this.attachEventListeners();
    this.measure();
    this.render();
  }

  setupDOM() {
    this.viewport = document.createElement('div');
    this.viewport.style.cssText = `
      position: relative;
      overflow-y: auto;
      overflow-x: hidden;
      height: 100%;
      width: 100%;
    `;

    this.virtualContainer = document.createElement('div');
    this.virtualContainer.style.cssText = `
      position: relative;
      width: 100%;
    `;

    this.itemsContainer = document.createElement('div');
    this.itemsContainer.style.cssText = `
      position: absolute;
      top: 0;
      left: 0;
      right: 0;
    `;

    this.virtualContainer.appendChild(this.itemsContainer);
    this.viewport.appendChild(this.virtualContainer);
    this.container.appendChild(this.viewport);
  }

  attachEventListeners() {
    this.viewport.addEventListener('scroll', this.handleScroll, { passive: true });
    window.addEventListener('resize', this.handleResize);
  }

  handleScroll() {
    this.scrollTop = this.viewport.scrollTop;
    this.isScrolling = true;

    if (this.scrollTimeout) clearTimeout(this.scrollTimeout);

    this.render();
    this.onScroll?.(this.scrollTop);

    this.scrollTimeout = setTimeout(() => {
      this.isScrolling = false;
    }, 150);
  }

  handleResize() {
    const oldHeight = this.containerHeight;
    this.measure();

    // If container height changed, re-render
    if (oldHeight !== this.containerHeight) {
      this.render();
    }
  }

  measure() {
    this.containerHeight = this.viewport.clientHeight;
  }

  /**
   * Invalidate positions from a given index onward
   */
  invalidatePositions(fromIndex) {
    this.dirtyStart = Math.min(this.dirtyStart, fromIndex);
    for (let i = fromIndex; i < this.items.length; i++) {
      this.itemPositions.delete(i);
    }
  }

  getItemPosition(index) {
    if (this.itemPositions.has(index)) {
      return this.itemPositions.get(index);
    }

    let position = 0;

    // Find the last cached position before this index
    for (let i = index - 1; i >= 0; i--) {
      if (this.itemPositions.has(i)) {
        position = this.itemPositions.get(i) + this.getItemHeight(i);
        // Calculate from here
        for (let j = i + 1; j <= index; j++) {
          position += this.getItemHeight(j);
        }
        break;
      }
    }

    // If no cached position found, calculate from start
    if (position === 0 && index > 0) {
      for (let i = 0; i < index; i++) {
        position += this.getItemHeight(i);
      }
    }

    this.itemPositions.set(index, position);
    return position;
  }

  getItemHeight(index) {
    if (this.itemHeights.has(index)) {
      return this.itemHeights.get(index);
    }
    return this.estimatedItemHeight;
  }

  measureItemHeight(element, index) {
    const height = element.offsetHeight;
    const cached = this.itemHeights.get(index);

    if (cached !== height) {
      this.itemHeights.set(index, height);
      this.invalidatePositions(index + 1);
    }
  }

  findVisibleRange() {
    const { scrollTop, containerHeight, items } = this;
    const viewportEnd = scrollTop + containerHeight;

    let start = this.binarySearch(scrollTop);
    let end = start;

    while (end < items.length && this.getItemPosition(end) < viewportEnd) {
      end++;
    }

    return { start, end };
  }

  binarySearch(scrollTop) {
    let left = 0;
    let right = this.items.length - 1;

    while (left < right) {
      const mid = Math.floor((left + right) / 2);
      const position = this.getItemPosition(mid);

      if (position < scrollTop) {
        left = mid + 1;
      } else {
        right = mid;
      }
    }

    return Math.max(0, left);
  }

  render() {
    const { start, end } = this.findVisibleRange();
    const overscanStart = Math.max(0, start - this.overscan);
    const overscanEnd = Math.min(this.items.length, end + this.overscan);

    this.visibleRange = { start: overscanStart, end: overscanEnd };

    const totalHeight = this.getTotalHeight();
    this.virtualContainer.style.height = `${totalHeight}px`;

    this.itemsContainer.innerHTML = '';
    const fragment = document.createDocumentFragment();

    for (let i = overscanStart; i < overscanEnd; i++) {
      const item = this.items[i];
      const element = this.itemRenderer(item, i);
      const position = this.getItemPosition(i);

      element.style.cssText += `
        position: absolute;
        top: ${position}px;
        left: 0;
        right: 0;
        box-sizing: border-box;
      `;

      element.dataset.index = i;
      fragment.appendChild(element);
    }

    this.itemsContainer.appendChild(fragment);

    // Measure heights
    this.itemsContainer.querySelectorAll('[data-index]').forEach((element) => {
      const index = parseInt(element.dataset.index, 10);
      this.measureItemHeight(element, index);
    });

    this.dirtyStart = Infinity;
  }

  getTotalHeight() {
    if (this.items.length === 0) return 0;
    const lastIndex = this.items.length - 1;
    return this.getItemPosition(lastIndex) + this.getItemHeight(lastIndex);
  }

  scrollToIndex(index, behavior = 'smooth') {
    const position = this.getItemPosition(index);
    this.viewport.scrollTo({
      top: position,
      behavior: this.scrollSmoothing ? behavior : 'auto',
    });
  }

  scrollToPosition(position, behavior = 'smooth') {
    this.viewport.scrollTo({
      top: position,
      behavior: this.scrollSmoothing ? behavior : 'auto',
    });
  }

  setItems(items) {
    this.items = items;
    this.itemHeights.clear();
    this.itemPositions.clear();
    this.dirtyStart = Infinity;
    this.scrollTop = 0;
    this.viewport.scrollTop = 0;
    this.render();
  }

  appendItems(items) {
    this.items.push(...items);
    this.render();
  }

  getScrollPosition() {
    return this.scrollTop;
  }

  getVisibleItems() {
    const { start, end } = this.visibleRange;
    return this.items.slice(start, end);
  }

  destroy() {
    this.viewport.removeEventListener('scroll', this.handleScroll);
    window.removeEventListener('resize', this.handleResize);
    if (this.scrollTimeout) clearTimeout(this.scrollTimeout);
    this.container.innerHTML = '';
  }
}
```

**Changes:**
- Bound handlers so `removeEventListener` works correctly
- Added `dirtyStart` to track which positions need recalculation
- `invalidatePositions()` now properly marks the range as dirty
- `getItemPosition()` optimized to find the nearest cached position and calculate from there
- `handleResize()` now re-renders only if container height actually changed

This handles the edge cases without sacrificing performance. The binary search still works because you're always calculating positions correctly, even with unmeasured items.

