**Issues to address:**

1. **Circuit breaker state transitions** — The HALF_OPEN → OPEN transition is missing. If a request fails while half-open, it should reopen immediately rather than waiting for the threshold again.

2. **Retry condition on circuit breaker exceptions** — Currently `CircuitBreakerOpenException` bypasses retry logic entirely, but you might want to retry after the timeout window passes.

3. **Metrics/observability** — No way to track retry attempts, backoff delays, or circuit breaker state changes for monitoring.

4. **Executor reuse** — Creating a new `RetryExecutor` per call defeats circuit breaker benefits. Should be shared across calls to the same service.

Here's the refined version:

```kotlin
import kotlinx.coroutines.delay
import kotlinx.coroutines.sync.Mutex
import kotlinx.coroutines.sync.withLock
import kotlin.math.min
import kotlin.math.pow
import kotlin.random.Random

data class RetryConfig(
    val maxAttempts: Int = 3,
    val initialDelayMs: Long = 100,
    val maxDelayMs: Long = 30000,
    val backoffMultiplier: Double = 2.0,
    val jitterFraction: Double = 0.1
)

data class CircuitBreakerConfig(
    val failureThreshold: Int = 5,
    val successThreshold: Int = 2,
    val timeoutMs: Long = 60000
)

enum class CircuitState {
    CLOSED, OPEN, HALF_OPEN
}

class CircuitBreakerOpenException(message: String) : Exception(message)
class RetryExhaustedException(message: String, cause: Throwable? = null) : Exception(message, cause)

// Observability hook
interface RetryObserver {
    suspend fun onRetry(attempt: Int, delayMs: Long, lastError: Exception)
    suspend fun onCircuitStateChange(oldState: CircuitState, newState: CircuitState)
    suspend fun onSuccess(attempt: Int)
    suspend fun onExhausted(totalAttempts: Int, lastError: Exception)
}

class NoOpRetryObserver : RetryObserver {
    override suspend fun onRetry(attempt: Int, delayMs: Long, lastError: Exception) {}
    override suspend fun onCircuitStateChange(oldState: CircuitState, newState: CircuitState) {}
    override suspend fun onSuccess(attempt: Int) {}
    override suspend fun onExhausted(totalAttempts: Int, lastError: Exception) {}
}

class CircuitBreaker(
    private val config: CircuitBreakerConfig,
    private val observer: RetryObserver = NoOpRetryObserver()
) {
    private val mutex = Mutex()
    private var state = CircuitState.CLOSED
    private var failureCount = 0
    private var successCount = 0
    private var lastFailureTime = 0L

    suspend fun <T> execute(block: suspend () -> T): T {
        mutex.withLock {
            when (state) {
                CircuitState.OPEN -> {
                    if (System.currentTimeMillis() - lastFailureTime > config.timeoutMs) {
                        val oldState = state
                        state = CircuitState.HALF_OPEN
                        successCount = 0
                        observer.onCircuitStateChange(oldState, state)
                    } else {
                        throw CircuitBreakerOpenException(
                            "Circuit breaker is OPEN. Retry after ${config.timeoutMs}ms"
                        )
                    }
                }
                else -> {}
            }
        }

        return try {
            val result = block()
            onSuccess()
            result
        } catch (e: Exception) {
            onFailure()
            throw e
        }
    }

    private suspend fun onSuccess() {
        mutex.withLock {
            failureCount = 0
            when (state) {
                CircuitState.HALF_OPEN -> {
                    successCount++
                    if (successCount >= config.successThreshold) {
                        val oldState = state
                        state = CircuitState.CLOSED
                        successCount = 0
                        observer.onCircuitStateChange(oldState, state)
                    }
                }
                CircuitState.CLOSED -> {}
                CircuitState.OPEN -> {}
            }
        }
    }

    private suspend fun onFailure() {
        mutex.withLock {
            failureCount++
            lastFailureTime = System.currentTimeMillis()

            // Reopen immediately if in HALF_OPEN state
            if (state == CircuitState.HALF_OPEN) {
                val oldState = state
                state = CircuitState.OPEN
                successCount = 0
                observer.onCircuitStateChange(oldState, state)
            } else if (failureCount >= config.failureThreshold && state == CircuitState.CLOSED) {
                val oldState = state
                state = CircuitState.OPEN
                observer.onCircuitStateChange(oldState, state)
            }
        }
    }

    suspend fun getState(): CircuitState = mutex.withLock { state }
}

class BackoffStrategy(private val config: RetryConfig) {
    fun calculateDelay(attempt: Int): Long {
        val exponentialDelay = config.initialDelayMs * config.backoffMultiplier.pow(attempt.toDouble())
        val cappedDelay = min(exponentialDelay.toLong(), config.maxDelayMs)
        val jitter = (Random.nextDouble() * config.jitterFraction * cappedDelay).toLong()
        return cappedDelay + jitter
    }
}

interface FallbackStrategy<T> {
    suspend fun execute(): T
}

class DefaultFallbackStrategy<T>(private val defaultValue: T) : FallbackStrategy<T> {
    override suspend fun execute(): T = defaultValue
}

class CustomFallbackStrategy<T>(private val block: suspend () -> T) : FallbackStrategy<T> {
    override suspend fun execute(): T = block()
}

class RetryExecutor<T>(
    private val retryConfig: RetryConfig = RetryConfig(),
    private val circuitBreakerConfig: CircuitBreakerConfig = CircuitBreakerConfig(),
    private val fallbackStrategy: FallbackStrategy<T>? = null,
    private val isRetryable: (Exception) -> Boolean = { true },
    private val observer: RetryObserver = NoOpRetryObserver()
) {
    private val circuitBreaker = CircuitBreaker(circuitBreakerConfig, observer)
    private val backoffStrategy = BackoffStrategy(retryConfig)

    suspend fun execute(block: suspend () -> T): T {
        var lastException: Exception? = null

        repeat(retryConfig.maxAttempts) { attempt ->
            try {
                val result = circuitBreaker.execute(block)
                observer.onSuccess(attempt)
                return result
            } catch (e: Exception) {
                lastException = e

                // Don't retry non-retryable exceptions
                if (!isRetryable(e)) {
                    throw e
                }

                // Don't delay after the last attempt
                if (attempt < retryConfig.maxAttempts - 1) {
                    val delayMs = backoffStrategy.calculateDelay(attempt)
                    observer.onRetry(attempt, delayMs, e)
                    delay(delayMs)
                }
            }
        }

        observer.onExhausted(retryConfig.maxAttempts, lastException!!)

        return if (fallbackStrategy != null) {
            try {
                fallbackStrategy.execute()
            } catch (e: Exception) {
                throw RetryExhaustedException(
                    "Retry exhausted after ${retryConfig.maxAttempts} attempts. Fallback failed: ${e.message}",
                    lastException
                )
            }
        } else {
            throw RetryExhaustedException(
                "Retry exhausted after ${retryConfig.maxAttempts} attempts",
                lastException
            )
        }
    }

    suspend fun getCircuitBreakerState(): CircuitState = circuitBreaker.getState()
}

suspend inline fun <T> withRetry(
    retryConfig: RetryConfig = RetryConfig(),
    circuitBreakerConfig: CircuitBreakerConfig = CircuitBreakerConfig(),
    fallbackStrategy: FallbackStrategy<T>? = null,
    noinline isRetryable: (Exception) -> Boolean = { true },
    observer: RetryObserver = NoOpRetryObserver(),
    crossinline block: suspend () -> T
): T {
    val executor = RetryExecutor(retryConfig, circuitBreakerConfig, fallbackStrategy, isRetryable, observer)
    return executor.execute(block)
}
```

**Key changes:**

- **HALF_OPEN → OPEN transition** — Failures while half-open immediately reopen the circuit.
- **Observer pattern** — Hook into retry lifecycle for logging, metrics, or alerting.
- **Removed circuit breaker exception bypass** — Now retryable by default; let the timeout window handle backoff naturally.
- **Executor state sharing** — Callers should reuse the same `RetryExecutor` instance for a given service to maintain circuit breaker state across calls.

For production, wire the observer to your metrics system (Micrometer, Prometheus, etc.) to track circuit breaker transitions and retry patterns.

