import { Semaphore } from 'async-sema'; // or similar library

class Node<K, V> {
  key: K;
  value: V;
  prev: Node<K, V> | null = null;
  next: Node<K, V> | null = null;
  timer?: NodeJS.Timeout;
  // Additional properties if necessary
}

class LRUCache<K, V> {
  private capacity: number;
  private map = new Map<K, Node<K, V>>();
  private head: Node<K, V> | null = null;
  private tail: Node<K, V> | null = null;
  private semaphore = new Semaphore(1);

  constructor(capacity: number) {
    this.capacity = capacity;
  }

  private async acquire() {
    await this.semaphore.acquire();
  }

  private release() {
    this.semaphore.release();
  }

  async put(key: K, value: V, ttl?: number) {
    await this.acquire();
    try {
      // Handle existing node
      const existingNode = this.map.get(key);
      if (existingNode) {
        if (existingNode.timer) {
          clearTimeout(existingNode.timer);
        }
        existingNode.value = value;
        // move to head
        this.moveToHead(existingNode);
      } else {
        // create node
        const node = new Node<K, V>(key, value);
        this.map.set(key, node);
        this.addNode(node);
        if (this.map.size > this.capacity) {
          this.removeTail();
        }
      }

      // Set TTL if provided
      if (ttl !== undefined) {
        const node = this.map.get(key)!;
        node.timer = setTimeout(() => {
          this.removeEntry(key);
        }, ttl);
      }
    } finally {
      this.release();
    }
  }

  private moveToHead(node: Node<K, V>) {
    // remove node from list
    this.removeNode(node);
    this.addNode(node);
  }

  private addNode(node: Node<K, V>) {
    node.next = this.head;
    node.prev = null;
    if (this.head) this.head.prev = node;
    this.head = node;
    if (!this.tail) this.tail = node;
  }

  private removeNode(node: Node<K, V>) {
    if (node.prev) node.prev.next = node.next;
    else this.head = node.next;

    if (node.next) node.next.prev = node.prev;
    else this.tail = node.prev;
  }

  private removeTail() {
    if (this.tail) {
      this.map.delete(this.tail.key);
      if (this.tail.timer) {
        clearTimeout(this.tail.timer);
      }
      this.removeNode(this.tail);
    }
  }

  async removeEntry(key: K) {
    await this.acquire();
    try {
      const node = this.map.get(key);
      if (node) {
        if (node.timer) {
          clearTimeout(node.timer);
        }
        this.removeNode(node);
        this.map.delete(key);
      }
    } finally {
      this.release();
    }
  }

  // Additional methods (get, etc.) would follow similar patterns
}
